31	const _supabaseUrl = String.fromEnvironment('SUPABASE_URL');
32	const _supabaseAnonKey = String.fromEnvironment('SUPABASE_ANON_KEY');
33	const _stripePublishableKey = String.fromEnvironment('STRIPE_PUBLISHABLE_KEY');
34	
35	void _assertEnvVars() {
36	  final missing = <String>[
37	    if (_supabaseUrl.isEmpty) 'SUPABASE_URL',
38	    if (_supabaseAnonKey.isEmpty) 'SUPABASE_ANON_KEY',
39	    if (_stripePublishableKey.isEmpty) 'STRIPE_PUBLISHABLE_KEY',
40	  ];
41	  if (missing.isNotEmpty) {
42	    throw StateError(
43	      'Missing required --dart-define variables: ${missing.join(', ')}.\n'
44	      'Run the app with:\n'
45	      '  flutter run \\\n'
46	      '    --dart-define=SUPABASE_URL=<url> \\\n'
47	      '    --dart-define=SUPABASE_ANON_KEY=<key> \\\n'
48	      '    --dart-define=STRIPE_PUBLISHABLE_KEY=<key>\n'
49	      'Or use: flutter run --dart-define-from-file=.env',
50	    );
51	  }
52	}
53	
54	bool _integrationTestBindingActive() {
55	  if (integration_test_gate.integrationTestActive) return true;
56	  try {
57	    final type = WidgetsBinding.instance.runtimeType.toString();
58	    return type.contains('IntegrationTest') ||
59	        type.contains('AutomatedTestWidgetsFlutterBinding');
60	  } catch (_) {
61	    return false;
62	  }
63	}
64	
65	Future<void> main() async {
66	  final integrationTest = _integrationTestBindingActive();
67	  final marionetteEnabled =
68	      !integrationTest && marionette_gate.marionetteEnabledInThisBuild;
69	  if (marionetteEnabled) {
70	    MarionetteBinding.ensureInitialized();
71	  } else if (!integrationTest) {
72	    WidgetsFlutterBinding.ensureInitialized();
73	  }
74	
75	  if (kIsWeb) {
76	    usePathUrlStrategy();
77	    // C6: Cap Flutter's in-memory image cache to 64 MB on web to prevent
78	    // unbounded growth in long-running sessions.
79	    PaintingBinding.instance.imageCache.maximumSizeBytes = 64 * 1024 * 1024;
80	  }
81	
82	  if (!integrationTest) {
83	    FlutterError.onError = (details) {
84	      FlutterError.presentError(details);
85	    };
86	    PlatformDispatcher.instance.onError = (error, stack) {
87	      debugPrint('Unhandled async error: $error\n$stack');
88	      return true;
89	    };
90	  }
91	
92	  _assertEnvVars();
93	  await PrefsSchema.migrate();
94	
95	  GoogleFonts.config.allowRuntimeFetching = kIsWeb;
96	
97	  if (!kIsWeb) {
98	    await ensureStripeReady(publishableKey: _stripePublishableKey);
99	  }
100	
101	  await Supabase.initialize(url: _supabaseUrl, publishableKey: _supabaseAnonKey);
102	
103	  if (kIsWeb) {
104	    runApp(const ProviderScope(child: PetfolioApp()));
105	    unawaited(_initializeWebPushStack());
106	    return;
107	  }
108	
109	  if (!integrationTest) {
110	    await NotificationService.instance.initialize(
111	      onTap: FcmService.instance.handleNotificationTap,
112	    );
113	    await PlatformNotifications.instance.initialize();
114	
115	    await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
116	    FirebaseMessaging.onBackgroundMessage(firebaseMessagingBackgroundHandler);
117	    await FcmService.instance.initialize();
118	  }
119	
120	  runApp(const ProviderScope(child: PetfolioApp()));
121	}
122	
123	Future<void> _initializeWebPushStack() async {
124	  try {
125	    await Firebase.initializeApp(
126	      options: DefaultFirebaseOptions.currentPlatform,
127	    );
128	    await FcmService.instance.initialize();
129	  } catch (e, stack) {
130	    debugPrint('Web push stack init failed: $e\n$stack');
131	  }
132	}
