141	
142	    FcmService.instance.updateRouter(router);
143	
144	    return MaterialApp.router(
145	      title: 'PetFolio',
146	      debugShowCheckedModeBanner: false,
147	      scaffoldMessengerKey: appSnackBarMessengerKey,
148	      theme: AppTheme.light(),
149	      darkTheme: AppTheme.dark(),
150	      themeMode: themeMode,
151	      routerConfig: router,
152	    );
153	  }
154	}
