149	  /// Parses a CSS hex string (`#RRGGBB` or `#AARRGGBB`) into a [Color].
150	  /// Returns [fallback] if the string is null, empty, or unparseable.
151	  static Color fromHexString(String? hex, {Color fallback = tangerine}) {
152	    if (hex == null || hex.isEmpty) return fallback;
153	    final clean = hex.replaceAll('#', '');
154	    try {
155	      if (clean.length == 6) return Color(int.parse('FF$clean', radix: 16));
156	      if (clean.length == 8) return Color(int.parse(clean, radix: 16));
157	    } catch (_) {}
158	    return fallback;
159	  }
160	}
