17	    _ref.listen<bool>(isLoggedInProvider, (previous, next) {
18	      if (previous != next) {
19	        _ref.invalidate(petListProvider);
20	        _ref.invalidate(isAdminProvider);
21	      }
22	      notifyListeners();
23	    });
24	    _ref.listen(petListProvider, (_, _) => notifyListeners());
25	  }
26	
27	  final Ref _ref;
28	
29	  FutureOr<String?> redirect(BuildContext context, GoRouterState state) {
30	    final isLoggedIn = _ref.read(isLoggedInProvider);
31	    final loc = state.matchedLocation;
32	    final path = state.uri.path;
33	
34	    if (_lastDismissedLocation != loc) {
35	      _lastDismissedLocation = loc;
36	      dismissRootOverlayRoutes(rootNavigatorKey);
37	    }
38	
39	    if (path == '/' || path.isEmpty) {
40	      return isLoggedIn ? '/home' : '/login';
41	    }
42	
43	    if (loc == '/pets') return '/home';
44	    if (loc == '/shop') return '/marketplace';
45	    if (loc == '/care/medical-vault') return '/care/health';
46	    if (loc == '/settings') return '/me';
47	    if (loc == '/social/notifications') return '/notifications';
48	
49	    if (!isLoggedIn) {
50	      return (loc == '/login' || loc == '/register') ? null : '/login';
51	    }
52	
53	    if (loc == '/login' || loc == '/register') return '/home';
54	
55	    final pets = _ref.read(petListProvider).value;
56	    if (pets != null && pets.isEmpty && loc != '/onboarding') {
57	      return '/onboarding';
58	    }
59	
60	    if (loc == '/onboarding' && pets != null && pets.isNotEmpty) {
61	      final mode = state.uri.queryParameters['mode'];
62	      if (mode != 'add') return '/care';
63	    }
64	
65	    if (loc.startsWith('/admin')) {
66	      final isAdmin = _ref.read(isAdminProvider);
67	      if (!isAdmin) return '/home';
68	    }
69	
70	    return null;
71	  }
72	}
