24	class CareRecommendationService {
25	  final _uuid = const Uuid();
26	
27	
28	
29	  /// Returns the AI-suggested tasks **and** the set of normalised existing
30	  /// task titles fetched from the DB. Callers use the existing-title set for
31	  /// duplicate detection against ALL pet tasks (not just today's view).
32	  Future<({List<CareTask> suggestions, Set<String> existingNormalised})>
33	      generateRecommendations(Pet pet) async {
34	
35	    final supabase = Supabase.instance.client;
36	
37	    final vaultFuture = supabase
38	        .from('medical_vault')
39	        .select('record_type, name, frequency, next_due_at')
40	        .eq('pet_id', pet.id)
41	        .eq('is_active', true)
42	        .limit(10);
43	
44	    final healthFuture = supabase
45	        .from('health_logs')
46	        .select('log_type, weight_kg, severity, diagnosis')
47	        .eq('pet_id', pet.id)
48	        .order('created_at', ascending: false)
49	        .limit(5);
50	
51	    final tasksFuture = supabase
52	        .from('care_tasks')
53	        .select('task_type, title')
54	        .eq('pet_id', pet.id)
55	        .limit(50);
56	
57	    final results = await Future.wait([vaultFuture, healthFuture, tasksFuture]);
58	
59	    final vault = (results[0] as List)
60	        .map((r) => Map<String, dynamic>.from(r as Map))
61	        .toList();
62	
63	    final healthLogs = (results[1] as List)
64	        .map((r) => Map<String, dynamic>.from(r as Map))
65	        .toList();
66	
67	    final existingTasks = (results[2] as List)
68	        .map((r) => {'type': r['task_type'] as String?, 'title': r['title'] as String?})
69	        .toList();
70	
71	    // Build a normalised set of ALL existing task titles for the pet.
72	    // Used by AiRoutineNotifier to detect duplicates against the full task
73	    // list — not just today's filtered view, which misses weekly/monthly tasks
74	    // that don't apply today.
75	    final existingNormalised = existingTasks
76	        .map((t) => _normaliseTitle(t['title'] ?? ''))
77	        .where((s) => s.isNotEmpty)
78	        .toSet();
79	
80	    final prompt = _buildPrompt(
81	      pet: pet,
82	      vault: vault,
83	      healthLogs: healthLogs,
84	      existingTasks: existingTasks,
85	    );
86	
87	    try {
88	      final fnResp = await Supabase.instance.client.functions
89	          .invoke('recommend-care-tasks', body: {'prompt': prompt})
90	          .timeout(const Duration(seconds: 60));
91	      if (fnResp.status != 200) {
92	        final detail = fnResp.data?.toString() ?? '';
93	        throw CareRecommendationException(
94	          'The suggestion service is unavailable right now. Please try again later.',
95	          cause: 'Edge function ${fnResp.status}: ${detail.length > 300 ? detail.substring(0, 300) : detail}',
96	        );
97	      }
98	      final Map<String, dynamic> body = (fnResp.data is Map)
99	          ? Map<String, dynamic>.from(fnResp.data as Map)
100	          : jsonDecode(jsonEncode(fnResp.data)) as Map<String, dynamic>;
101	
102	      final content = body['choices'][0]['message']['content'] as String;
103	
104	      final cleaned = content
105	          .replaceAll(RegExp(r'```json\s*'), '')
106	          .replaceAll(RegExp(r'```\s*'), '')
107	          .trim();
108	
109	      final arrayMatch = RegExp(r'\[[\s\S]*\]').firstMatch(cleaned);
110	      final arrayStr = arrayMatch?.group(0) ?? cleaned;
111	
112	      final jsonList = jsonDecode(arrayStr) as List;
113	      final now = DateTime.now();
114	      final tasks = <CareTask>[];
115	
116	      for (final item in jsonList) {
117	        if (item is! Map) continue;
118	        final taskTypeStr = _pick(item, const [
119	              'taskType', 'task_type', 'type', 'category', 'care_type'
120	            ]) ??
121	            'other';
122	        final taskType = _parseTaskType(taskTypeStr);
123	
124	        final rawTitle = _pick(item, const [
125	          'title', 'task_name', 'name', 'task_title', 'label'
126	        ]);
127	        final title = (rawTitle != null &&
128	                rawTitle.isNotEmpty &&
129	                rawTitle.toLowerCase() != 'care task')
130	            ? rawTitle
131	            : _defaultTitleForType(taskType);
132	
133	        final freqStr = _pick(item, const [
134	              'frequency', 'schedule_frequency', 'schedule', 'recurrence'
135	            ]) ??
136	            'daily';
137	
138	        final rawTime = _pick(item, const [
139	          'scheduledTime', 'scheduled_time', 'time', 'schedule_time'
140	        ]);
141	        final scheduledTime = _normalizeTime(rawTime);
142	
143	        final points = (_numPick(item, const [
144	                  'gamificationPoints',
145	                  'gamification_points',
146	                  'points',
147	                  'xp'
148	                ]))
149	                ?.toInt() ??
150	            _defaultPoints(_parseFrequency(freqStr));
151	
152	        final notes = _pick(item, const ['notes', 'note', 'description', 'reason']);
153	
154	        tasks.add(CareTask(
155	          id: _uuid.v4(),
156	          petId: pet.id,
157	          taskType: taskType,
158	          title: title,
159	          frequency: _parseFrequency(freqStr),
160	          scheduledTime: scheduledTime,
161	          isCompleted: false,
162	          gamificationPoints: points,
163	          notes: notes,
164	          createdAt: now,
165	          updatedAt: now,
166	        ));
167	      }
168	      return (suggestions: tasks, existingNormalised: existingNormalised);
169	    } on CareRecommendationException {
170	      rethrow;
171	    } catch (e) {
172	      throw CareRecommendationException(
173	        'Could not generate care suggestions. Please try again.',
174	        cause: e,
175	      );
176	    }
177	  }
