274	  static String? _pick(Map item, List<String> keys) {
275	    // Exact match first
276	    for (final k in keys) {
277	      final v = item[k];
278	      if (v is String && v.isNotEmpty) return v;
279	    }
280	    // Case-insensitive fallback against all map keys
281	    final lowerKeys = keys.map((k) => k.toLowerCase()).toSet();
282	    for (final entry in item.entries) {
283	      final keyLower = entry.key.toString().toLowerCase();
284	      if (lowerKeys.contains(keyLower)) {
285	        final v = entry.value;
286	        if (v is String && v.isNotEmpty) return v;
287	      }
288	    }
289	    return null;
290	  }
291	
292	  static num? _numPick(Map item, List<String> keys) {
293	    for (final k in keys) {
294	      final v = item[k];
295	      if (v is num) return v;
296	    }
297	    return null;
298	  }
299	
300	  static String? _normalizeTime(String? raw) {
301	    if (raw == null || raw.isEmpty || raw == 'null') return null;
302	    // Accept HH:MM or HH:MM:SS — keep only HH:MM
303	    final parts = raw.split(':');
304	    if (parts.length >= 2) {
305	      final h = int.tryParse(parts[0]);
306	      final m = int.tryParse(parts[1]);
307	      if (h != null && m != null) {
308	        return '${h.toString().padLeft(2, '0')}:${m.toString().padLeft(2, '0')}';
309	      }
310	    }
311	    return null;
312	  }
