409	  static CareFrequency _parseFrequency(String s) {
410	    switch (s.toLowerCase().replaceAll(RegExp(r'[\s_-]'), '')) {
411	      case 'daily':
412	      case 'everyday':
413	      case 'eachday':
414	        return CareFrequency.daily;
415	      case 'twicedaily':
416	      case 'twiceaday':
417	      case '2xdaily':
418	      case '2daily':
419	        return CareFrequency.twiceDaily;
420	      case 'weekly':
421	      case 'onceaweek':
422	      case 'everyweek':
423	        return CareFrequency.weekly;
424	      case 'biweekly':
425	      case 'every2weeks':
426	      case 'everyotherweek':
427	      case 'fortnightly':
428	        return CareFrequency.biweekly;
429	      case 'monthly':
430	      case 'onceamonth':
431	      case 'everymonth':
432	        return CareFrequency.monthly;
433	      case 'asneeded':
434	      case 'whenneeded':
435	      case 'occasionally':
436	      case 'asrequired':
