8	enum LocationAccessState {
9	  granted,
10	  denied,
11	  permanentlyDenied,
12	  servicesDisabled,
13	  unavailable,
14	}
15	
16	class LocationService {
17	  Future<LocationAccessState> readAccessState() async {
18	    try {
19	      if (!kIsWeb && !await Geolocator.isLocationServiceEnabled()) {
20	        return LocationAccessState.servicesDisabled;
21	      }
22	      return _mapGeolocatorPermission(await Geolocator.checkPermission());
23	    } catch (_) {
24	      return LocationAccessState.unavailable;
25	    }
26	  }
27	
28	  Future<LocationAccessState> requestWhenInUseAccess() async {
29	    try {
30	      if (!kIsWeb && !await Geolocator.isLocationServiceEnabled()) {
31	        return LocationAccessState.servicesDisabled;
32	      }
33	      return _mapGeolocatorPermission(await Geolocator.requestPermission());
34	    } catch (_) {
35	      return LocationAccessState.unavailable;
36	    }
37	  }
38	
39	  LocationAccessState _mapGeolocatorPermission(LocationPermission permission) {
40	    switch (permission) {
41	      case LocationPermission.always:
42	      case LocationPermission.whileInUse:
43	        return LocationAccessState.granted;
44	      case LocationPermission.denied:
45	        return LocationAccessState.denied;
46	      case LocationPermission.deniedForever:
47	        return LocationAccessState.permanentlyDenied;
48	      case LocationPermission.unableToDetermine:
49	        return LocationAccessState.denied;
50	    }
51	  }
52	
53	  Future<LatLng> acquireCurrentLatLng() async {
54	    var access = await readAccessState();
55	
56	    if (access == LocationAccessState.denied) {
57	      access = await requestWhenInUseAccess();
58	    }
59	
60	    switch (access) {
61	      case LocationAccessState.servicesDisabled:
62	        throw const ValidationException(
63	          message:
