91	      final pos = await Geolocator.getCurrentPosition(
92	        locationSettings: LocationSettings(
93	          accuracy: LocationAccuracy.medium,
94	          timeLimit: Duration(seconds: kIsWeb ? 15 : 20),
95	        ),
96	      );
97	      return LatLng(latitude: pos.latitude, longitude: pos.longitude);
98	    } on ValidationException {
